8	// ForeachAddcmulList host-side: tiling computation + kernel launch
9	
10	#include "torch_kernel_helper.h"
11	#include "tiling/platform/platform_ascendc.h"
12	#include "aclrtlaunch_foreach_addcmul_list.h"
13	
14	namespace ascend_kernel {
15	
16	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
17	
18	at::Tensor foreach_addcmul_list(
19	    const at::Tensor &x1,
20	    const at::Tensor &x2,
21	    const at::Tensor &x3,
22	    const at::Tensor &scalars)
23	{
24	    // Input validation
25	    TORCH_CHECK(x1.scalar_type() == at::kHalf ||
26	                x1.scalar_type() == at::kBFloat16 ||
27	                x1.scalar_type() == at::kFloat ||
28	                x1.scalar_type() == at::kInt,
29	                "foreach_addcmul_list: only float16, bfloat16, float32, int32 are supported, got ",
30	                x1.scalar_type());
31	
32	    int64_t totalLength = x1.numel();
33	    if (totalLength == 0) {
34	        return at::empty_like(x1);
35	    }
36	
37	    // Determine output dtype
38	    at::ScalarType outputDtype = x1.scalar_type();
39	    if (x1.scalar_type() == at::kBFloat16) {
40	        outputDtype = at::kFloat;
41	    }
42	
43	    at::Tensor output = at::empty({totalLength}, x1.options().dtype(outputDtype));
44	
45	    int64_t dtypeSize = x1.element_size();
46	    int64_t outputSize = (x1.scalar_type() == at::kBFloat16) ? 4 : dtypeSize;
47	
48	    // Get hardware parameters
49	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
50	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
51	    uint64_t ubSize;
52	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
53	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
54	
55	    // Block-level tiling (cache-line aligned)
56	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
57	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
58	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
59	
60	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
61	    int64_t formerNum = usedCoreNum - 1;
62	    int64_t formerLength = totalLengthCoreAlign;
63	    int64_t tailLength = totalLength - formerNum * formerLength;
64	
65	    // Check if int32
66	    int64_t isInt32 = (x1.scalar_type() == at::kInt) ? 1 : 0;
67	
68	    // UB-level tiling: bufferCoefficient from UB allocation table
69	    // 4 input queues (VECIN, BUFFER_NUM=2) + 1 output queue (VECOUT, BUFFER_NUM=2)
70	    //   fp16:  (4*2*2 + 1*2*2) = 20 bytes/element
71	    //   bf16:  (4*2*2 + 1*2*4 + 5*4) = 44 bytes/element (extra fp32 cast bufs)
72	    //   fp32/int32:  (4*2*4 + 1*2*4) = 40 bytes/element
73	    int64_t bufferCoefficient;
74	    if (x1.scalar_type() == at::kBFloat16) {
75	        bufferCoefficient = 44;
76	    } else if (dtypeSize == 2) {
77	        bufferCoefficient = 20;  // fp16
78	    } else {
79	        bufferCoefficient = 40;  // fp32 / int32
80	    }
81	
82	    if (bufferCoefficient <= 0) { bufferCoefficient = 1; }
83	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
84	    int64_t alignElements = (dtypeSize > 0) ? (32 / dtypeSize) : 1;
85	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
86	    if (tileLength <= 0) { tileLength = alignElements; }
87	
88	    // All EXEC_KERNEL_CMD arguments must be lvalues
89	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
90	    int64_t formerNumVal = formerNum;
91	    int64_t formerLengthVal = formerLength;
92	    int64_t tailLengthVal = tailLength;
93	    int64_t tileLengthVal = tileLength;
94	    int64_t dtypeSizeVal = dtypeSize;
95	    int64_t outputSizeVal = outputSize;
96	
97	    int64_t isInt32Val = isInt32;
98	
99	    EXEC_KERNEL_CMD(foreach_addcmul_list, blockDim,
100	                    x1, x2, x3, scalars, output,
101	                    formerNumVal, formerLengthVal, tailLengthVal,
102	                    tileLengthVal, dtypeSizeVal, outputSizeVal, isInt32Val);
103	
104	    return output;
105	}
106	
107	}  // namespace ascend_kernel
