7	
8	// ForeachAddcmulList device kernel
9	// Computation: output[i] = x1[i] + scalars[i] * x2[i] * x3[i]
10	//
11	// dtype dispatch (by dtypeSize / outputSize):
12	//   float16     (2 / 2): direct compute in fp16
13	//   bfloat16    (2 / 4): upcast to fp32, compute in fp32, output fp32
14	//   float32     (4 / 4): direct compute in fp32
15	
16	#include "kernel_operator.h"
17	
18	constexpr int32_t BUFFER_NUM = 2;
19	
20	template <typename T, typename TOUT>
21	class KernelForeachAddcmulList {
22	public:
23	    __aicore__ inline KernelForeachAddcmulList() {}
24	
25	    __aicore__ inline void Init(GM_ADDR x1, GM_ADDR x2, GM_ADDR x3,
26	                                 GM_ADDR scalars, GM_ADDR output,
27	                                 int64_t formerNum, int64_t formerLength,
28	                                 int64_t tailLength, int64_t tileLength)
29	    {
30	        int64_t blockIdx = AscendC::GetBlockIdx();
31	
32	        if (blockIdx < formerNum) {
33	            this->blockLength = formerLength;
34	            int64_t offset = formerLength * blockIdx;
35	            x1Gm.SetGlobalBuffer((__gm__ T *)x1 + offset, formerLength);
36	            x2Gm.SetGlobalBuffer((__gm__ T *)x2 + offset, formerLength);
37	            x3Gm.SetGlobalBuffer((__gm__ T *)x3 + offset, formerLength);
38	            scalarsGm.SetGlobalBuffer((__gm__ T *)scalars + offset, formerLength);
39	            outputGm.SetGlobalBuffer((__gm__ TOUT *)output + offset, formerLength);
40	        } else {
41	            this->blockLength = tailLength;
42	            int64_t tailIdx = blockIdx - formerNum;
43	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
44	            x1Gm.SetGlobalBuffer((__gm__ T *)x1 + offset, tailLength);
45	            x2Gm.SetGlobalBuffer((__gm__ T *)x2 + offset, tailLength);
46	            x3Gm.SetGlobalBuffer((__gm__ T *)x3 + offset, tailLength);
47	            scalarsGm.SetGlobalBuffer((__gm__ T *)scalars + offset, tailLength);
48	            outputGm.SetGlobalBuffer((__gm__ TOUT *)output + offset, tailLength);
49	        }
50	
51	        this->tileLength = tileLength;
52	
53	        // Init queues: 4 inputs (VECIN) + 1 output (VECOUT)
54	        pipe.InitBuffer(inQueueX1, BUFFER_NUM, tileLength * sizeof(T));
55	        pipe.InitBuffer(inQueueX2, BUFFER_NUM, tileLength * sizeof(T));
56	        pipe.InitBuffer(inQueueX3, BUFFER_NUM, tileLength * sizeof(T));
57	        pipe.InitBuffer(inQueueS, BUFFER_NUM, tileLength * sizeof(T));
58	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(TOUT));
59	
60	        // For bf16: allocate fp32 compute buffers
61	        if constexpr (std::is_same_v<T, bfloat16_t>) {
62	            pipe.InitBuffer(castBuf1, tileLength * sizeof(float));
63	            pipe.InitBuffer(castBuf2, tileLength * sizeof(float));
64	            pipe.InitBuffer(castBuf3, tileLength * sizeof(float));
65	            pipe.InitBuffer(castBufS, tileLength * sizeof(float));
66	            pipe.InitBuffer(computeBuf, tileLength * sizeof(float));
67	        }
68	    }
69	
70	    __aicore__ inline void Process()
71	    {
72	        if (this->blockLength == 0) {
73	            return;
74	        }
75	
76	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
77	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
78	
79	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
80	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
81	
82	        for (int64_t i = 0; i < tileNum - 1; ++i) {
83	            CopyIn(i, this->tileLength);
84	            Compute(i, this->tileLength);
85	            CopyOut(i, this->tileLength);
86	        }
87	        if (tileNum > 0) {
88	            int64_t lastIdx = tileNum - 1;
89	            CopyIn(lastIdx, alignedTailLen);
90	            Compute(lastIdx, alignedTailLen);
91	            CopyOut(lastIdx, alignedTailLen);
92	        }
93	    }
94	
95	private:
96	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
97	    {
98	        AscendC::LocalTensor<T> x1Local = inQueueX1.AllocTensor<T>();
99	        AscendC::LocalTensor<T> x2Local = inQueueX2.AllocTensor<T>();
100	        AscendC::LocalTensor<T> x3Local = inQueueX3.AllocTensor<T>();
101	        AscendC::LocalTensor<T> sLocal = inQueueS.AllocTensor<T>();
102	
103	        AscendC::DataCopy(x1Local, x1Gm[progress * this->tileLength], curTileLength);
104	        AscendC::DataCopy(x2Local, x2Gm[progress * this->tileLength], curTileLength);
105	        AscendC::DataCopy(x3Local, x3Gm[progress * this->tileLength], curTileLength);
106	        AscendC::DataCopy(sLocal, scalarsGm[progress * this->tileLength], curTileLength);
107	
108	        inQueueX1.EnQue(x1Local);
109	        inQueueX2.EnQue(x2Local);
110	        inQueueX3.EnQue(x3Local);
111	        inQueueS.EnQue(sLocal);
112	    }
113	
114	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
115	    {
116	        AscendC::LocalTensor<T> x1Local = inQueueX1.DeQue<T>();
117	        AscendC::LocalTensor<T> x2Local = inQueueX2.DeQue<T>();
118	        AscendC::LocalTensor<T> x3Local = inQueueX3.DeQue<T>();
119	        AscendC::LocalTensor<T> sLocal = inQueueS.DeQue<T>();
120	        AscendC::LocalTensor<TOUT> yLocal = outQueueY.AllocTensor<TOUT>();
121	
122	        if constexpr (std::is_same_v<T, bfloat16_t>) {
123	            // bfloat16 path: upcast to fp32, compute, output fp32
124	            AscendC::LocalTensor<float> x1Fp32 = castBuf1.Get<float>();
125	            AscendC::LocalTensor<float> x2Fp32 = castBuf2.Get<float>();
126	            AscendC::LocalTensor<float> x3Fp32 = castBuf3.Get<float>();
127	            AscendC::LocalTensor<float> sFp32 = castBufS.Get<float>();
128	            AscendC::LocalTensor<float> tmpFp32 = computeBuf.Get<float>();
129	
130	            AscendC::Cast(x1Fp32, x1Local, AscendC::RoundMode::CAST_NONE, curTileLength);
131	            AscendC::Cast(x2Fp32, x2Local, AscendC::RoundMode::CAST_NONE, curTileLength);
132	            AscendC::Cast(x3Fp32, x3Local, AscendC::RoundMode::CAST_NONE, curTileLength);
133	            AscendC::Cast(sFp32, sLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
134	
135	            // tmp = x2 * x3
136	            AscendC::Mul(tmpFp32, x2Fp32, x3Fp32, curTileLength);
137	            // tmp = scalars * tmp
138	            AscendC::Mul(tmpFp32, sFp32, tmpFp32, curTileLength);
139	            // output = x1 + tmp  (fp32 output, yLocal is LocalTensor<float>)
140	            AscendC::Add(yLocal, x1Fp32, tmpFp32, curTileLength);
141	        } else {
142	            // float16 / float32 path: direct compute in input dtype
143	            // For fp32: T=float, TOUT=float; for fp16: T=half, TOUT=half
144	            // Use yLocal as temporary first, then add x1
145	            // Actually, need a separate temp buffer for intermediate results
146	            // yLocal type is TOUT = T for these paths, so we can use it directly
147	
148	            // First: yLocal = x2 * x3 (using output buffer as temp)
149	            AscendC::Mul(yLocal, x2Local, x3Local, curTileLength);
150	            // yLocal = scalars * yLocal
151	            AscendC::Mul(yLocal, sLocal, yLocal, curTileLength);
152	            // yLocal = x1 + yLocal
153	            AscendC::Add(yLocal, x1Local, yLocal, curTileLength);
154	        }
155	
156	        outQueueY.EnQue<TOUT>(yLocal);
157	        inQueueX1.FreeTensor(x1Local);
158	        inQueueX2.FreeTensor(x2Local);
159	        inQueueX3.FreeTensor(x3Local);
160	        inQueueS.FreeTensor(sLocal);
161	    }
162	
163	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
164	    {
165	        AscendC::LocalTensor<TOUT> yLocal = outQueueY.DeQue<TOUT>();
166	        AscendC::DataCopy(outputGm[progress * this->tileLength], yLocal, curTileLength);
167	        outQueueY.FreeTensor(yLocal);
168	    }
169	
170	private:
171	    AscendC::TPipe pipe;
172	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX1;
173	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX2;
174	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX3;
175	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueS;
176	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
177	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf1;
178	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf2;
179	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf3;
180	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufS;
181	    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf;
182	    AscendC::GlobalTensor<T> x1Gm;
183	    AscendC::GlobalTensor<T> x2Gm;
184	    AscendC::GlobalTensor<T> x3Gm;
185	    AscendC::GlobalTensor<T> scalarsGm;
186	    AscendC::GlobalTensor<TOUT> outputGm;
187	    int64_t blockLength;
188	    int64_t tileLength;
189	};
190	
191	
192	extern "C" __global__ __aicore__ void foreach_addcmul_list(
193	    GM_ADDR x1, GM_ADDR x2, GM_ADDR x3, GM_ADDR scalars, GM_ADDR output,
194	    int64_t formerNum, int64_t formerLength, int64_t tailLength,
195	    int64_t tileLength, int64_t dtypeSize, int64_t outputSize,
196	    int64_t isInt32)
197	{
198	    // Dispatch based on input dtype size and output dtype size
199	    if (dtypeSize == 2 && outputSize == 2) {
200	        // float16: T=half, TOUT=half
201	        KernelForeachAddcmulList<half, half> op;
202	        op.Init(x1, x2, x3, scalars, output,
203	                formerNum, formerLength, tailLength, tileLength);
204	        op.Process();
205	    } else if (dtypeSize == 2 && outputSize == 4) {
206	        // bfloat16: T=bfloat16_t, TOUT=float (upcast → fp32 compute → fp32 output)
207	        KernelForeachAddcmulList<bfloat16_t, float> op;
208	        op.Init(x1, x2, x3, scalars, output,
209	                formerNum, formerLength, tailLength, tileLength);
210	        op.Process();
211	    } else if (isInt32) {
212	        // int32: T=int32_t, TOUT=int32_t
213	        KernelForeachAddcmulList<int32_t, int32_t> op;
214	        op.Init(x1, x2, x3, scalars, output,
215	                formerNum, formerLength, tailLength, tileLength);
216	        op.Process();
217	    } else {
218	        // float32: T=float, TOUT=float
219	        KernelForeachAddcmulList<float, float> op;
220	        op.Init(x1, x2, x3, scalars, output,
221	                formerNum, formerLength, tailLength, tileLength);
222	        op.Process();
223	    }
224	}
