// ForeachAddcmulScalarList device kernel
// Computation: output[i] = x1[i] + scalars[i] * x2[i] * x3[i]
//
// dtype dispatch (by dtypeSize / outputSize):
//   float16     (2 / 2): direct compute in fp16
//   bfloat16    (2 / 4): upcast to fp32, compute in fp32, output fp32
//   float32     (4 / 4): direct compute in fp32
//   int32       (4 / 4): direct compute in int32

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T, typename TOUT>
class KernelForeachAddcmulScalarList {
public:
    __aicore__ inline KernelForeachAddcmulScalarList() {}

    __aicore__ inline void Init(GM_ADDR x1, GM_ADDR x2, GM_ADDR x3,
                                 GM_ADDR scalars, GM_ADDR output,
                                 int64_t formerNum, int64_t formerLength,
                                 int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            x1Gm.SetGlobalBuffer((__gm__ T *)x1 + offset, formerLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2 + offset, formerLength);
            x3Gm.SetGlobalBuffer((__gm__ T *)x3 + offset, formerLength);
            scalarsGm.SetGlobalBuffer((__gm__ T *)scalars + offset, formerLength);
            outputGm.SetGlobalBuffer((__gm__ TOUT *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            x1Gm.SetGlobalBuffer((__gm__ T *)x1 + offset, tailLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2 + offset, tailLength);
            x3Gm.SetGlobalBuffer((__gm__ T *)x3 + offset, tailLength);
            scalarsGm.SetGlobalBuffer((__gm__ T *)scalars + offset, tailLength);
            outputGm.SetGlobalBuffer((__gm__ TOUT *)output + offset, tailLength);
        }

        this->tileLength = tileLength;

        // Init queues: 4 inputs (VECIN) + 1 output (VECOUT)
        pipe.InitBuffer(inQueueX1, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueX2, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueX3, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueS, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(TOUT));

        // For bf16: allocate fp32 compute buffers
        if constexpr (std::is_same_v<T, bfloat16_t>) {
            pipe.InitBuffer(castBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(castBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(castBuf3, tileLength * sizeof(float));
            pipe.InitBuffer(castBufS, tileLength * sizeof(float));
            pipe.InitBuffer(computeBuf, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if (this->blockLength == 0) {
            return;
        }

        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            int64_t lastIdx = tileNum - 1;
            CopyIn(lastIdx, alignedTailLen);
            Compute(lastIdx, alignedTailLen);
            CopyOut(lastIdx, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> x1Local = inQueueX1.AllocTensor<T>();
        AscendC::LocalTensor<T> x2Local = inQueueX2.AllocTensor<T>();
        AscendC::LocalTensor<T> x3Local = inQueueX3.AllocTensor<T>();
        AscendC::LocalTensor<T> sLocal = inQueueS.AllocTensor<T>();

        AscendC::DataCopy(x1Local, x1Gm[progress * this->tileLength], curTileLength);
        AscendC::DataCopy(x2Local, x2Gm[progress * this->tileLength], curTileLength);
        AscendC::DataCopy(x3Local, x3Gm[progress * this->tileLength], curTileLength);
        AscendC::DataCopy(sLocal, scalarsGm[progress * this->tileLength], curTileLength);

        inQueueX1.EnQue(x1Local);
        inQueueX2.EnQue(x2Local);
        inQueueX3.EnQue(x3Local);
        inQueueS.EnQue(sLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> x1Local = inQueueX1.DeQue<T>();
        AscendC::LocalTensor<T> x2Local = inQueueX2.DeQue<T>();
        AscendC::LocalTensor<T> x3Local = inQueueX3.DeQue<T>();
        AscendC::LocalTensor<T> sLocal = inQueueS.DeQue<T>();
        AscendC::LocalTensor<TOUT> yLocal = outQueueY.AllocTensor<TOUT>();

        if constexpr (std::is_same_v<T, bfloat16_t>) {
            // bfloat16 path: upcast to fp32, compute, output fp32
            AscendC::LocalTensor<float> x1Fp32 = castBuf1.Get<float>();
            AscendC::LocalTensor<float> x2Fp32 = castBuf2.Get<float>();
            AscendC::LocalTensor<float> x3Fp32 = castBuf3.Get<float>();
            AscendC::LocalTensor<float> sFp32 = castBufS.Get<float>();
            AscendC::LocalTensor<float> tmpFp32 = computeBuf.Get<float>();

            AscendC::Cast(x1Fp32, x1Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(x2Fp32, x2Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(x3Fp32, x3Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(sFp32, sLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

            // tmp = x2 * x3
            AscendC::Mul(tmpFp32, x2Fp32, x3Fp32, curTileLength);
            // tmp = scalars * tmp
            AscendC::Mul(tmpFp32, sFp32, tmpFp32, curTileLength);
            // output = x1 + tmp  (fp32 output)
