#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_foreach_addcmul_scalar_list.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor foreach_addcmul_scalar_list(
    const at::Tensor &x1,
    const at::Tensor &x2,
    const at::Tensor &x3,
    const at::Tensor &scalars)
{
    // Input validation
    TORCH_CHECK(x1.scalar_type() == at::kHalf ||
                x1.scalar_type() == at::kBFloat16 ||
                x1.scalar_type() == at::kFloat ||
                x1.scalar_type() == at::kInt,
                "foreach_addcmul_scalar_list: only float16, bfloat16, float32, int32 are supported, got ",
                x1.scalar_type());

    int64_t totalLength = x1.numel();
    if (totalLength == 0) {
        return at::empty_like(x1);
    }

    // Determine output dtype
    at::ScalarType outputDtype = x1.scalar_type();
    if (x1.scalar_type() == at::kBFloat16) {
        outputDtype = at::kFloat;
    }

    at::Tensor output = at::empty({totalLength}, x1.options().dtype(outputDtype));

    int64_t dtypeSize = x1.element_size();
    int64_t outputSize = (x1.scalar_type() == at::kBFloat16) ? 4 : dtypeSize;

    // Get hardware parameters
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // Block-level tiling (cache-line aligned)
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // Check if int32
    int64_t isInt32 = (x1.scalar_type() == at::kInt) ? 1 : 0;

    // UB-level tiling: bufferCoefficient from UB allocation table
    // 4 input queues (VECIN, BUFFER_NUM=2) + 1 output queue (VECOUT, BUFFER_NUM=2)
    //   fp16:  (4*2*2 + 1*2*2) = 20 bytes/element
    //   bf16:  (4*2*2 + 1*2*4 + 5*4) = 44 bytes/element (extra fp32 cast bufs)
    //   fp32/int32:  (4*2*4 + 1*2*4) = 40 bytes/element
    int64_t bufferCoefficient;
    if (x1.scalar_type() == at::kBFloat16) {
        bufferCoefficient = 44;
    } else if (dtypeSize == 2) {
        bufferCoefficient = 20;  // fp16
    } else {
        bufferCoefficient = 40;  // fp32 / int32
    }

    if (bufferCoefficient <= 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = (dtypeSize > 0) ? (32 / dtypeSize) : 1;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength <= 0) { tileLength = alignElements; }

    // All EXEC_KERNEL_CMD arguments must be lvalues
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int64_t formerNumVal = formerNum;
    int64_t formerLengthVal = formerLength;
    int64_t tailLengthVal = tailLength;
    int64_t tileLengthVal = tileLength;
    int64_t dtypeSizeVal = dtypeSize;
    int64_t outputSizeVal = outputSize;
    int64_t isInt32Val = isInt32;

    EXEC_KERNEL_CMD(foreach_addcmul_scalar_list, blockDim,
                    x1, x2, x3, scalars, output,
                    formerNumVal, formerLengthVal, tailLengthVal,
                    tileLengthVal, dtypeSizeVal, outputSizeVal, isInt32Val);

    return output;
}

}  // namespace ascend_kernel
